WITH cleaned AS (SELECT id, session_id, event_type, page, event_time, duration_sec, CONCAT(page, ' - ', event_type) AS page_event_type, COALESCE(page, 'NONE') AS page_clean FROM web_events WHERE event_time >= DATE '2023-05-05'), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM cleaned), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('YEAR', event_time) AS year_start, DATE_TRUNC('MONTH', event_time) AS activity_month, COUNT(*) AS event_count, SUM(new_group_flag) AS total_new_group_flag, MIN(event_time) AS started_at, COUNT(*) AS cnt, GROUPING(DATE_TRUNC('YEAR', event_time)) AS grouping_level FROM sessionized GROUP BY CUBE (DATE_TRUNC('YEAR', event_time), DATE_TRUNC('MONTH', event_time)) ORDER BY activity_month NULLS LAST;
